package controller;
import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.Pane;import javafx.scene.shape.Circle;import javafx.animation.*;import javafx.util.Duration;import service.*;import java.util.Random;
public final class MainMenuController {@FXML private Pane particles;@FXML private Button startButton;@FXML private Label welcomeLabel,startLockLabel;@FXML public void initialize(){GameManager game=GameManager.getInstance();welcomeLabel.setText("WELCOME, "+game.getPlayer().getName().toUpperCase());boolean unlocked=game.hasCompletedLearningNotes();startButton.setDisable(!unlocked);startLockLabel.setText(unlocked?"All learning topics complete • Mission access granted":"Complete all 6 Learning Notes topics to unlock Start Game ("+game.completedLearningTopicCount()+" / 6)");Random r=new Random();for(int i=0;i<18;i++){Circle c=new Circle(3+r.nextDouble()*7);c.getStyleClass().add("bubble");c.setLayoutX(r.nextDouble()*1150);c.setLayoutY(100+r.nextDouble()*600);particles.getChildren().add(c);TranslateTransition t=new TranslateTransition(Duration.seconds(4+r.nextDouble()*5),c);t.setByY(-650);t.setCycleCount(Animation.INDEFINITE);t.setDelay(Duration.seconds(r.nextDouble()*4));t.play();}}@FXML private void start(){if(GameManager.getInstance().hasCompletedLearningNotes())SceneManager.switchScene("Level1.fxml");}@FXML private void notes(){SceneManager.switchScene("LearningNotes.fxml");}@FXML private void how(){SceneManager.switchScene("HowToPlay.fxml");}@FXML private void achievements(){SceneManager.switchScene("Achievements.fxml");}@FXML private void exit(){SceneManager.getStage().close();}}
